CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), github_id bigint UNIQUE, github_login text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, version text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(user_id,version));
CREATE TABLE IF NOT EXISTS integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, provider text NOT NULL, external_id text, token_ciphertext text, scopes text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(user_id,provider));
CREATE TABLE IF NOT EXISTS repositories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, github_repo_id bigint NOT NULL, full_name text NOT NULL, private boolean NOT NULL, default_branch text, selected boolean NOT NULL DEFAULT false, analyzed_at timestamptz, UNIQUE(user_id,github_repo_id));
CREATE TABLE IF NOT EXISTS claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, concept text NOT NULL, source text NOT NULL, source_ref text, target_role text, importance_weight numeric NOT NULL DEFAULT 1 CHECK(importance_weight>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, claim_id uuid REFERENCES claims ON DELETE SET NULL, kind text NOT NULL CHECK(kind IN ('repository','resume','assessment','leetcode')), source_ref text NOT NULL, excerpt text, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), provenance jsonb NOT NULL DEFAULT '{}', observed_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);
CREATE TABLE IF NOT EXISTS rules(id text PRIMARY KEY, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verdicts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, claim_id uuid REFERENCES claims ON DELETE SET NULL, tier text NOT NULL, coverage numeric, rule_id text NOT NULL REFERENCES rules(id), reason text NOT NULL, evidence_refs uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS challenges(id text NOT NULL, version text NOT NULL, prompt text NOT NULL, starter text NOT NULL, hidden_tests text NOT NULL, rubric jsonb NOT NULL, quality_status text NOT NULL DEFAULT 'unvalidated', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, challenge_id text NOT NULL, challenge_version text NOT NULL, rubric jsonb NOT NULL, status text NOT NULL, score numeric, outcomes jsonb NOT NULL DEFAULT '{}', submitted_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, FOREIGN KEY(challenge_id,challenge_version) REFERENCES challenges(id,version));
CREATE TABLE IF NOT EXISTS reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES assessments ON DELETE CASCADE, reviewer_id uuid REFERENCES users ON DELETE SET NULL, reason text NOT NULL, decision text, notes text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS assessment_quality_samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES assessments ON DELETE CASCADE, reviewer_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, automated_score numeric, human_decision text NOT NULL, matches_automated boolean NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS challenge_quality_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id text NOT NULL, challenge_version text NOT NULL, reference_passed boolean NOT NULL, weak_rejected boolean NOT NULL, details jsonb NOT NULL, run_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(challenge_id,challenge_version) REFERENCES challenges(id,version));
CREATE TABLE IF NOT EXISTS followups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, claim_id uuid NOT NULL REFERENCES claims ON DELETE CASCADE, questions jsonb NOT NULL, answers jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), answered_at timestamptz);
CREATE TABLE IF NOT EXISTS cohorts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, name text NOT NULL, invite_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cohort_members(cohort_id uuid NOT NULL REFERENCES cohorts ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cohort_id,user_id));
CREATE TABLE IF NOT EXISTS learning_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, claim_id uuid REFERENCES claims ON DELETE SET NULL, recommendation text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS passports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, fields jsonb NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, object_type text NOT NULL, object_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO rules(id,definition) VALUES ('evidence-v1.0.0','{"repositoryConfidenceThreshold":0.65,"freshnessDays":90,"coverage":"weighted supported claims / eligible claim weight"}') ON CONFLICT DO NOTHING;
INSERT INTO challenges(id,version,prompt,starter,hidden_tests,rubric,quality_status) VALUES ('python-string-tools','1.0.0','Implement normalize_words(text): return lowercase words with punctuation removed, preserving word order.','def normalize_words(text):\n    raise NotImplementedError\n','[{"input":"Hello, WORLD!","expected":["hello","world"]},{"input":"","expected":[]},{"input":"one-two","expected":["onetwo"]}]','{"correctness":80,"edgeCases":20}','unvalidated') ON CONFLICT DO NOTHING;
